def _number(value, cast=float):
    """*value* as a finite number, or None for anything else (strings, lists, NaN, booleans)."""
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        return None
    if value != value or abs(value) > 1e12:
        return None
    return cast(value)
